-- Seed tamareen question bank from the existing static bank.
-- Run after supabase/schema.sql in Supabase SQL Editor.

insert into public.questions (course_id, question, correct_answer, wrong_answers, explanation)
select c.id, v.question, v.correct_answer, v.wrong_answers::jsonb, v.explanation
from public.courses c
cross join (values
  ('Which concept is best described as: “executes Python instructions”?','Python interpreter','["variable","bool","elif"]','Python interpreter executes Python instructions.'),
