  ('Which course concept is illustrated by this example: for item in items:?','for loop','["operator precedence","print()","string slicing"]','The example illustrates for loop.'),
  ('Which statement about for loop is correct?','iterates over a sequence','["try/except","extracts part of a string","represents whole numbers"]','for loop iterates over a sequence.'),
  ('Which concept is best described as: “extracts part of a string”?','string slicing','["list","int","comparison operator"]','string slicing extracts part of a string.'),
  ('What is the main purpose or value of string slicing?','accesses a substring by indexes','["stores an ordered mutable collection","represents decimal numbers","chooses between two alternatives"]','string slicing is important because it accesses a substring by indexes.'),
  ('Which course concept is illustrated by this example: name[0:3]?','string slicing','["comparison operator","int","list"]','The example illustrates string slicing.'),
  ('Which statement about string slicing is correct?','extracts part of a string','["name + age","stores an ordered mutable collection","represents decimal numbers"]','string slicing extracts part of a string.'),
  ('Which concept is best described as: “stores an ordered mutable collection”?','list','["dictionary","float","if statement"]','list stores an ordered mutable collection.'),
  ('What is the main purpose or value of list?','supports indexed multi-value data','["stores key-value pairs","represents text","tests additional conditions"]','list is important because it supports indexed multi-value data.'),
  ('Which course concept is illustrated by this example: [10,20,30]?','list','["if statement","float","dictionary"]','The example illustrates list.'),
  ('Which statement about list is correct?','stores an ordered mutable collection','["{''a'':1}","stores key-value pairs","represents text"]','list stores an ordered mutable collection.'),
  ('Which concept is best described as: “stores key-value pairs”?','dictionary','["Python interpreter","str","if/else"]','dictionary stores key-value pairs.'),
  ('What is the main purpose or value of dictionary?','supports lookup by meaningful keys','["executes Python instructions","represents True or False","handles runtime exceptions"]','dictionary is important because it supports lookup by meaningful keys.'),
  ('Which course concept is illustrated by this example: {''name'':''Ali''}?','dictionary','["if/else","str","Python interpreter"]','The example illustrates dictionary.'),
  ('Which statement about dictionary is correct?','stores key-value pairs','["[1,2,3]","executes Python instructions","represents True or False"]','dictionary stores key-value pairs.')
) as v(question, correct_answer, wrong_answers, explanation)
where c.code='BCIS 313';

insert into public.questions (course_id, question, correct_answer, wrong_answers, explanation)
select c.id, v.question, v.correct_answer, v.wrong_answers::jsonb, v.explanation
from public.courses c
cross join (values
  ('Which concept is best described as: “integrates enterprise processes and data”?','ERP system','["functional silo","procurement module","configuration"]','ERP system integrates enterprise processes and data.'),
